                { ab: true, options: ['やはり／ところだった', 'いったい／のか', 'といっても／わけでもない', 'たしかに／ことは間違いない'], correct: 3 },
                { options: ['見させてしまう', '身を乗り出させる', '見られてしまう', '身を乗り出される'], correct: 0 },
                { ab: true, options: ['ぼく／みんな', '広告主／みんな', '広告主／ぼくも', 'ぼく／広告主も'], correct: 0 }
