    var retakeConfirmed = false;
    function isPassageQ(q) { return !!q && (q.type === 'Comprehension' || q.type === 'Text Grammar'); }
    nextBtn.addEventListener('click', function() {
        speechSession++;
        window.speechSynthesis.cancel();
        blankPopup.classList.remove('active');
        if (isFinished) {
            if (isViewingResults) {
                // starting again clears this set's answers: ask first (a quick second tap on 「試験を終了する」 landed here)
                if (!retakeConfirmed) {
                    showConfirm('もう一度解く', '今の解答を消して、最初から解き直します。\n間違えた問題は、解き直すまで誤答ノートに残ります。', 'もう一度解く', false, function() { retakeConfirmed = true; nextBtn.click(); });
                    return;
                }
                retakeConfirmed = false;
                if (isMistakeMode) {
                    currentQuestions.forEach(function(q) { delete userAnswers[q.id]; });
                    saveAnswers();
                    isFinished = false; isReviewing = false; isViewingResults = false;
                    resumeData['bookmark'] = 0;
                    sessionStartedAt = Date.now();
                    currentIndex = 0; score = 0; answerHistory = [];
                    updateHistoryUI();
                    loadQuestion();
                    return;
                }
                if (isBookmarkMode) {
                    currentQuestions.forEach(function(q) {
                        delete userAnswers[q.id];
                    });
                } else if (selectedWeek === 'all') {
                    // 全範囲 is per book: clear only this book's answers
                    libQuestions(selectedLib).forEach(function(q) { delete allModeAnswers[q.id]; });
                    userAnswers = allModeAnswers;
                } else {
                    var w = parseInt(selectedWeek);
                    // まとめて解く retakes every tile in the section; otherwise just this day
                    var dList = selectedDay === 'unit'
                        ? Array.apply(null, Array(daysIn(getLib(selectedLib), w))).map(function(x, i) { return i + 1; })
                        : [parseInt(selectedDay)];
                    var heldScores = loadJSON('jlptHeldScores', {});
                    dList.forEach(function(d) {
                        var dk = dayKey(selectedLib, w, d);
                        resetDayTimer(dk);
                        var before = dayStatus(w, d, selectedLib);
                        if (before.answered > 0) heldScores[dk] = { earned: before.earned, answered: before.answered, max: before.max };
                        quizData.forEach(function(q) {
                            if (q.lib === selectedLib && q.week === w && q.day === d) {
                                forgetReadTimer(q.id);
                                if (typeof userAnswers[q.id] === 'string' && !isQuestionCorrect(q)) retakeMistakes[q.id] = { answer: userAnswers[q.id], time: mistakeTimestamps[q.id] || Date.now() };
                                delete userAnswers[q.id];
                                delete progressData[q.id + '_answered'];
                                for (var bi = 0; bi < 10; bi++) delete progressData[q.id + '_' + bi + '_answered'];
                            }
                        });
                        progressData[dk] = { total: 0, correct: 0 };
                    });
                    localStorage.setItem('jlptHeldScores', JSON.stringify(heldScores));
                    localStorage.setItem('jlptProgress', JSON.stringify(progressData));
                    localStorage.setItem('jlptRetakeMistakes', JSON.stringify(retakeMistakes));
                }
                saveAnswers();

                if (!isBookmarkMode) {
                    var key = dayKey(selectedLib, selectedWeek, selectedDay);
                    resumeData[key] = 0;
                    delete shuffledOrders[key];
                    localStorage.setItem('jlptResume', JSON.stringify(resumeData));
                    localStorage.setItem('jlptShuffledOrders', JSON.stringify(shuffledOrders));
                }

                startQuiz();
            } else {
                showResults();
            }
            return;
        }
        if (isReviewing) {
            var rKey = currentModeKey();
            currentIndex = resumeData[rKey] || 0;
            isReviewing = false;
            loadQuestion();
            return;
        }
        var prevQ = currentQuestions[currentIndex];
        currentIndex++;
        if (currentIndex < currentQuestions.length) {
            var nKey = currentModeKey();
            resumeData[nKey] = currentIndex;
            localStorage.setItem('jlptResume', JSON.stringify(resumeData));
            loadQuestion();
            // a new reading passage starts at the top (questions on the same passage keep the reader's place)
            var nextQ = currentQuestions[currentIndex];
            if (isPassageQ(prevQ) || isPassageQ(nextQ)) {
                if (!(prevQ && nextQ && prevQ.group && prevQ.group === nextQ.group)) window.scrollTo(0, 0);
            }
        } else {
            showResults();
        }
    });

    dashboardToggle.addEventListener('click', showDashboard);
