    bookmarksToggle.addEventListener('click', showBookmarks);
    mistakesToggle.addEventListener('click', showMistakes);

    // In-app confirmation dialog. The browser's built-in confirm() is blocked in some viewers
    // (file previews, in-app browsers), where it silently returns false — which made the reset buttons do nothing.
    function showConfirm(title, message, okLabel, danger, onOk) {
        var overlay = document.getElementById('confirm-overlay');
        var okBtn = document.getElementById('confirm-ok');
        var cancelBtn = document.getElementById('confirm-cancel');
        document.getElementById('confirm-title').textContent = title;
        document.getElementById('confirm-message').textContent = message;
        okBtn.textContent = okLabel;
        okBtn.classList.toggle('danger', !!danger);
        cancelBtn.style.display = '';
        overlay.classList.add('active');
        var close = function() {
            overlay.classList.remove('active');
            okBtn.onclick = null; cancelBtn.onclick = null; overlay.onclick = null;
        };
        okBtn.onclick = function() { close(); onOk(); };
        cancelBtn.onclick = close;
        overlay.onclick = function(e) { if (e.target === overlay) close(); };
        cancelBtn.focus();
    }

    resetProgressBtn.addEventListener('click', function() {
        showConfirm('成績表をリセット', 'すべての解答が消去され、誤答ノートも空になります。\n（統計とブックマークは残ります）', 'リセットする', true, function() {
            reportAnswers = {};
            localStorage.removeItem('jlptHeldScores');
            localStorage.removeItem('jlptDayTimer'); dayTimes = {}; timerRun = null;
            if (!isAllModeActive()) userAnswers = reportAnswers;
            progressData = {};
            resumeData = {};
            shuffledOrders = {};
            mistakeTimestamps = {};
            localStorage.setItem('jlptUserAnswers', JSON.stringify(reportAnswers));
            localStorage.setItem('jlptAnswerShadow', '{}');
            localStorage.removeItem('jlptProgress');
            localStorage.setItem('jlptResume', JSON.stringify(resumeData));
            localStorage.setItem('jlptShuffledOrders', JSON.stringify(shuffledOrders));
            localStorage.setItem('jlptMistakeTimestamps', JSON.stringify(mistakeTimestamps));
            showDashboard();
        });
    });

    var isResettingAll = false;

    // ===================== Word list (long press to add) =====================
    // Long-press any word in a question (sentence, passage, answer choices, word-order pieces, passage blanks)
    // to add it to 単語帳. The word under the finger is found with Intl.Segmenter, and can be adjusted before saving.
    var wordList = loadJSON('jlptWordList', []);
    if (!Array.isArray(wordList)) wordList = [];
    // ---- 単語帳: one card per word ----
    // Two cards are the same word when they match ignoring spaces and full-width/half-width differences.
    // Merging keeps every meaning (different ones joined with ／), every sentence and source the word was found in
    // (e.others), the earliest date, a checked reading, and the review step that comes due first.
    function normWord(w) { return String(w || '').normalize('NFKC').replace(/[\s\u3000]/g, ''); }
    function wordPlaces(e) {
        return [{ qid: e.qid || null, source: e.source || '', context: e.context || '', added: e.added }].concat(e.others || []);
    }
    function placeKey(p) { return (p.qid || '') + '|' + (p.context || '') + '|' + (p.qid ? '' : p.source || ''); }
    function mergeWordInto(a, b) {
        var parts = [];
        [a.meaning, b.meaning].forEach(function(m) {
            String(m || '').split(/\s*／\s*/).forEach(function(x) { x = x.trim(); if (x && parts.map(normWord).indexOf(normWord(x)) === -1) parts.push(x); });
        });
        a.meaning = parts.join(' ／ ');
        if (!(a.readingChecked && a.reading) && (b.reading || b.furigana)) { a.furigana = b.furigana || ''; a.reading = b.reading || ''; a.readingChecked = !!b.readingChecked; }
        var places = [], seen = {};
        wordPlaces(a).concat(wordPlaces(b)).forEach(function(p) {
            if (!p.qid && !p.source && !p.context) return;
            var k = placeKey(p); if (seen[k]) return; seen[k] = 1; places.push(p);
        });
        places.sort(function(x, y) { return (x.added || 0) - (y.added || 0); });
        var first = places[0] || { qid: null, source: '', context: '' };
        a.qid = first.qid || null; a.source = first.source || ''; a.context = first.context || '';
        a.others = places.slice(1).map(function(p) { return { qid: p.qid || null, source: p.source || '', context: p.context || '', added: p.added || a.added }; });
        if (!a.others.length) delete a.others;
        a.added = Math.min(a.added || Date.now(), b.added || Date.now());
        // review progress: a copy never reviewed doesn't count; between two reviewed copies, the one due first, so nothing is skipped
        var revA = !!(a.due || a.box), revB = !!(b.due || b.box);
        if (revB && (!revA || (b.due || '') < (a.due || '') || ((b.due || '') === (a.due || '') && (b.box || 0) < (a.box || 0)))) { a.box = b.box || 0; if (b.due) a.due = b.due; else delete a.due; }
        return a;
    }
    // a sentence (or source) this word was found in, added to its card if it is new
    function addWordPlace(e, qid, source, context) {
        var p = { qid: qid || null, source: source || '', context: context || '', added: Date.now() };
        if (!p.qid && !p.source && !p.context) return;
        var k = placeKey(p);
        if (wordPlaces(e).some(function(x) { return placeKey(x) === k; })) return;
        if (!e.qid && !e.source && !e.context) { e.qid = p.qid; e.source = p.source; e.context = p.context; return; }
        (e.others = e.others || []).push(p);
    }
    function tidyWordList() {
        var byWord = {}, out = [], merged = 0;
        wordList.forEach(function(e) {
            var k = normWord(e.word);
            if (!k) { out.push(e); return; }
            if (byWord[k]) { mergeWordInto(byWord[k], e); merged++; }
            else { byWord[k] = e; out.push(e); }
        });
        if (merged) wordList = out;
        return merged;
    }
    var wordDupesMerged = tidyWordList();
    // one pass over saved words: automatic readings into [ ] form
    setTimeout(function() { try { var before = JSON.stringify(wordList); wordList.forEach(function(e) { addDictionaryLine(e); autoBracketFurigana(e); }); setTimeout(checkDictForms, 3000); if (JSON.stringify(wordList) !== before) localStorage.setItem('jlptWordList', JSON.stringify(wordList)); } catch (e) {} }, 0);     // once everything it uses is defined
    if (wordDupesMerged) {
        try { localStorage.setItem('jlptWordList', JSON.stringify(wordList)); } catch (e) {}
        setTimeout(function() { if (typeof showToast === 'function') showToast('単語帳の重複を' + wordDupesMerged + '件まとめました'); }, 3000);
    }
    var LONG_PRESS_MS = 500;
    var LONG_PRESS_MOVE_PX = 10;
    var LONG_PRESS_TARGETS = '.ar-line, .ar-h p, .ar-card-q, .kj-q, .kj-res-sent, .ar-ex > div:first-of-type, .ab-say, .kw-text, .sentence-text, .reading-box p, .reading-box td, .reading-box, .reading-intro, .option-btn, .comp-sentence, .drag-item, .inline-slot, .direction-box, .reading-notes, .question-text';
    var pressTimer = null, pressStart = null, suppressClickUntil = 0;
    var wordSheetState = null;   // { text, start, end, context, qid, editId }
    var currentWordSort = 'new';

    function saveWordList() {
        wordList.forEach(function(e) { addDictionaryLine(e); autoBracketFurigana(e); });
        setTimeout(checkDictForms, 500);
        localStorage.setItem('jlptWordList', JSON.stringify(wordList));
    }
    // ---------- 辞書形: 関わっている → 関わる, 勧められた → 勧める, 高かった → 高い ----------
    // Rule-based: every way back to a dictionary form is collected; words the app already knows come first.
    var GODAN_A = { 'わ': 'う', 'か': 'く', 'が': 'ぐ', 'さ': 'す', 'た': 'つ', 'な': 'ぬ', 'ば': 'ぶ', 'ま': 'む', 'ら': 'る' };
    var GODAN_I = { 'い': 'う', 'き': 'く', 'ぎ': 'ぐ', 'し': 'す', 'ち': 'つ', 'に': 'ぬ', 'び': 'ぶ', 'み': 'む', 'り': 'る' };
    var GODAN_E = { 'え': 'う', 'け': 'く', 'げ': 'ぐ', 'せ': 'す', 'て': 'つ', 'ね': 'ぬ', 'べ': 'ぶ', 'め': 'む', 'れ': 'る' };
    var LEXICAL_RERU = ['生まれる', '産まれる', '恵まれる', '含まれる', '囲まれる'];
    var KARU_VERBS = ['分かる', '助かる', '掛かる', '預かる', '授かる', '見つかる', '引っかかる', '遠ざかる', '儲かる', '浸かる', '乗っかる', '差し掛かる', '取り掛かる', '寄りかかる', '向かう', '従う'];
    var ICHIDAN_I = '用率報老強悔';            // kanji + いる that are ichidan (用いる, 率いる …)
    var ICHIDAN_TE1 = '着見寝出似煮得経居射干';   // one-kanji ichidan verbs whose て-form is just kanji + て
    // Every way back to a dictionary form, each with a penalty (lower = more likely)
    function dictCandidates(word) {
        var out = {}, list = [];
        var add = function(w, pen) {
            if (!w || w === word || !/[うくぐすつぬぶむるい]$/.test(w)) return;
            if (out[w] === undefined) { out[w] = pen; list.push(w); } else if (pen < out[w]) out[w] = pen;
        };
        var last = function(x) { return x.slice(-1); };
        var isKanjiCh = function(ch) { return !!ch && hasKanji(ch); };
        var ichidanStemOk = function(st) { var ch = last(st); return isKanjiCh(ch) || /[いきぎしじちにひびみりえけげせぜてでねへべめれ]/.test(ch); };
        function verb(s, pen, depth) {        // s is a dictionary-form verb; a passive / causative is taken back to its base
            depth = depth || 0;
            add(s, pen);
            if (depth > 2 || LEXICAL_RERU.indexOf(s) !== -1) return;
            var m;
            if ((m = s.match(/^(.+)(?:られる|させる)$/)) && ichidanStemOk(m[1])) verb(m[1] + 'る', pen - 0.5, depth + 1);
            if ((m = s.match(/^(.+)([わかがさたなばまら])(?:れる|せる)$/)) && !isKanjiCh(m[2])) verb(m[1] + GODAN_A[m[2]], pen - 0.5, depth + 1);
            if ((m = s.match(/^(.*[一-鿿々]{2})される$/))) verb(m[1] + 'する', pen - 0.6, depth + 1);
        }
        function teOrTa(stem, pen) {          // the word without its て/た/で/だ
            var m;
            if ((m = stem.match(/^(.+)っ$/))) {
                if (/行$/.test(m[1])) { verb(m[1] + 'く', pen); pen += 1; }
                verb(m[1] + 'る', pen); verb(m[1] + 'う', pen + 0.2); verb(m[1] + 'つ', pen + 0.4);
            }
            else if ((m = stem.match(/^(.+)ん$/))) { verb(m[1] + 'む', pen); verb(m[1] + 'ぶ', pen + 0.2); verb(m[1] + 'ぬ', pen + 0.4); }
            else if ((m = stem.match(/^(.+)い$/))) {
                var ich = ICHIDAN_I.indexOf(last(m[1])) !== -1;
                verb(m[1] + 'く', pen + (ich ? 1 : 0)); verb(stem + 'る', pen + (ich ? 0 : 1)); verb(m[1] + 'ぐ', pen + 2);
            }
            else if ((m = stem.match(/^(.+)し$/))) {
                var before = m[1], ch = last(before), suru = !isKanjiCh(ch) ? !GODAN_A[ch] : /[一-鿿々]{2}$/.test(before);
                verb(before + 'する', pen + (suru ? 0 : 1)); verb(before + 'す', pen + (suru ? 1 : 0));
            }
            else if (stem && ichidanStemOk(stem)) verb(stem + 'る', pen);      // 着て, 鍛えて, 古びて → ichidan
        }
        function renyou(stem, pen) {
            var ch = last(stem);
            if (ch === 'し' && stem.length > 1) { verb(stem.slice(0, -1) + 'する', pen + (/[一-鿿々]{2}$/.test(stem.slice(0, -1)) ? 0 : 0.5)); }
            if (GODAN_I[ch] && stem.length > 1) verb(stem.slice(0, -1) + GODAN_I[ch], pen);
            if (stem.length && ichidanStemOk(stem)) verb(stem + 'る', pen + (GODAN_I[ch] ? 1 : 0));
        }
        function mizen(stem, pen) {
            var ch = last(stem);
            if (isKanjiCh(ch) && (ICHIDAN_TE1 + '来').indexOf(ch) === -1) return;     // 少ない, 危ない are adjectives
            if ((ch === 'さ' || ch === 'し') && stem.length > 1) verb(stem.slice(0, -1) + 'する', pen + 0.5);
            if (GODAN_A[ch] && stem.length > 1) verb(stem.slice(0, -1) + GODAN_A[ch], pen);
            else if (stem.length && ichidanStemOk(stem)) verb(stem + 'る', pen);
        }
        var s = word, m;
        // い-adjectives (分かった is a verb, 高かった an adjective)
        if ((m = s.match(/^(.+)(?:かった|くて|くない|くなかった|ければ|くなる|くなった|くなって)$/))) add(m[1] + 'い', KARU_VERBS.indexOf(m[1].replace(/か$/, '') + 'かる') !== -1 ? 1 : 0);
        if ((m = s.match(/^(.+)かった$/)) && KARU_VERBS.indexOf(m[1] + 'かる') !== -1) add(m[1] + 'かる', 0);
        // て-form helpers and their own endings: ている, ていた, ています, てしまった, ておく …
        if ((m = s.match(/^(.+)[てで](?:いる|いた|います|いました|いない|いなかった|いて|る|た|しまう|しまった|しまって|しまいます|おく|おいた|おいて|ある|あった|いく|いった|くる|きた|みる|みた|みて|ほしい)$/))) teOrTa(m[1], -0.3);
        if ((m = s.match(/^(.+)(?:ちゃう|ちゃった|じゃう|じゃった|とく|といた)$/))) teOrTa(m[1], -0.2);
        if ((m = s.match(/^(.+)(?:て|た|たり|たら|ても)$/))) {
            var st = m[1];
            if (isKanjiCh(last(st)) && st.replace(/[^一-鿿々]/g, '').length === st.length && st.length === 1 && ICHIDAN_TE1.indexOf(st) === -1) {}
            else if (isKanjiCh(last(st)) && !/[一-鿿々]$/.test(st.slice(0, -1)) && st.length > 1 && /て$/.test(s)) add(s + 'る', 0);   // 駆り立て → 駆り立てる
            else teOrTa(st, 0);
        }
        if ((m = s.match(/^(.+)(?:で|だ|だり|だら|でも)$/))) teOrTa(m[1], 0);
        if ((m = s.match(/^(.+)(?:ます|ました|ません|ませんでした|ましょう|たい|たかった|たくない|たくて|ながら|そうだ|そうな|そうに)$/))) renyou(m[1], 0);
        if ((m = s.match(/^(.+)(?:ない|なかった|なくて|ないで|なければ|なきゃ|ず|ずに|ぬ|ないと|なくなる)$/))) mizen(m[1], 0);
        if ((m = s.match(/^(.+)([えけげせてねべめれ])ば$/))) verb(m[1] + GODAN_E[m[2]], 0);
        if ((m = s.match(/^(.+)れば$/)) && ichidanStemOk(m[1])) verb(m[1] + 'る', 0.5);
        // passive / causative stems left bare: 鍛えられ, 閉ざされ
        if ((m = s.match(/^(.+)(?:られ|させ)$/))) verb(m[1] + 'られる', 0);
        if ((m = s.match(/^(.+)([わかがさたなばまら])れ$/)) && !isKanjiCh(m[2])) verb(m[1] + m[2] + 'れる', 0);
        return list.map(function(w) { return { w: w, p: out[w] }; });
    }
    // set phrases and adjectives that only look conjugated
    var NOT_CONJUGATED = ['いざ知らず', '相変わらず', '思わず', '絶えず', '少なからず', '知らず知らず', '我知らず', '必ず', '取りあえず', '取り敢えず',
        '情けない', '頼りない', '果てしない', '申し訳ない', '物足りない', '何気ない', '素っ気ない', '呆気ない', '仕方ない', '仕方がない', '切ない', '少ない', '危ない',
        'やむを得ない', '止むを得ない', '勿体ない', '味気ない', '心ない', 'だらしない', 'みっともない', 'とんでもない', '途方もない', '他ならない', '堪らない', '詰まらない', '下らない', '構わない', '済まない'];
    function dictionaryForm(word) {
        word = String(word || '').trim();
        if (!word || !hasKanji(word) || NOT_CONJUGATED.indexOf(word) !== -1) return null;
        var c = dictCandidates(word);
        if (!c.length) return null;
        var map = readingMap();
        var known = function(w) { return !!(wordDefinitions[w] || map[w] || readingCache[w] || wordList.some(function(e) { return e.word === w; })); };
        c.forEach(function(x, i) { x.i = i; });
        c.sort(function(a, b) { return (known(b.w) - known(a.w)) || (a.p - b.p) || (a.i - b.i); });
        return { form: c[0].w, alts: c.map(function(x) { return x.w; }) };
    }
    // The first line of a word's メモ is its dictionary form, when the saved word is conjugated.
    // Done once per spelling of the word (deleting the line keeps it deleted).
    function addDictionaryLine(e) {
        if (!e || !e.word || e.dictFor === e.word) return;
        e.dictFor = e.word;
        var d = dictionaryForm(e.word);
        if (!d) { delete e.dictForm; return; }
        e.dictForm = d.form;
        if (d.alts.length > 1) e.dictAlts = d.alts; else delete e.dictAlts;
        var m = String(e.meaning || '');
        if (m.split('\n')[0].trim() !== d.form) e.meaning = d.form + (m ? '\n' + m : '');
    }
    // When there was more than one way back, ask Wiktionary which of them is a real word (once, in the background)
    var checkingDictForms = false;
    function checkDictForms() {
        if (checkingDictForms || navigator.onLine === false) return;
        var todo = wordList.filter(function(e) { return e.dictAlts && !e.dictChecked; });
        if (!todo.length) return;
        checkingDictForms = true;
        var changed = false;
        (function next() {
            var e = todo.shift();
            if (!e) { checkingDictForms = false; if (changed) saveWordList(); return; }
            var alts = e.dictAlts.slice(0, 4), i = 0;
            (function tryOne() {
                if (i >= alts.length) { e.dictChecked = true; changed = true; next(); return; }
                var w = alts[i++];
                lookUpReadingOnline(w).then(function(r) {
                    if (!r) { if (Object.prototype.hasOwnProperty.call(readingCache, w)) tryOne(); else { next(); } return; }
                    if (w !== e.dictForm) {
                        var lines = String(e.meaning || '').split('\n');
                        if (lines[0].trim() === e.dictForm) { lines[0] = w; e.meaning = lines.join('\n'); }
                        e.dictForm = w;
                        if (typeof renderWordListItems === 'function' && wordlistView && wordlistView.style.display !== 'none') renderWordListItems();
                    }
                    e.dictChecked = true; changed = true; next();
                });
            })();
        })();
    }
    // An automatic reading is written into the word in [ ] form (例文 + れいぶん → 例[れい]文[ぶん]), so it shows,
    // edits and exports the same way as furigana you typed yourself. Only when it reads back as the same word.
    function autoBracketFurigana(e) {
        if (!e || e.furigana || !e.reading || !hasKanji(e.word)) return;
        var html = furiganaHtml(e.word, e.reading);
        if (html.indexOf('<ruby>') === -1) return;
        var src = html.replace(/<ruby>(.*?)<\/ruby>/g, function(m, inner) { return inner.replace(/(.*?)<rt>(.*?)<\/rt>/g, '$1[$2]'); })
            .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
        var back = parseBracketFurigana(src);
        if (back && back.word === e.word && toHiragana(back.reading) === toHiragana(e.reading)) e.furigana = back.source;
    }
    // ---- 単語帳: 元に戻す・やり直す ----
    // Each step remembers only the cards it changed (as they were before and after), so undoing one step
    // leaves everything else as it is now, e.g. cards reviewed since. Automatic changes (readings looked up,
    // カードで復習) are not steps. Kept while the app is open, up to 50 steps.
    var wordUndo = [], wordRedo = [];
    function wordSnap() { var m = {}; wordList.forEach(function(e, i) { m[e.id] = { j: JSON.stringify(e), i: i }; }); return m; }
    function wordBegin() { return wordSnap(); }
    function wordCommit(before, label) {
        var after = wordSnap(), ch = {}, any = false;
        Object.keys(before).concat(Object.keys(after)).forEach(function(id) {
            var b = before[id] || null, a = after[id] || null;
            if ((b && b.j) !== (a && a.j) && !ch[id]) { ch[id] = { b: b, a: a }; any = true; }
        });
        if (!any) return;
        wordUndo.push({ label: label, ch: ch });
        if (wordUndo.length > 50) wordUndo.shift();
        wordRedo = [];
        updateWordUndoUi();
    }
    function wordApply(ch, side) {
        Object.keys(ch).forEach(function(id) {
            var st = ch[id][side], idx = wordList.findIndex(function(e) { return e.id === id; });
            if (!st) { if (idx >= 0) wordList.splice(idx, 1); return; }
            var obj = JSON.parse(st.j), other = ch[id][side === 'a' ? 'b' : 'a'];
            if (idx < 0) { wordList.splice(Math.min(st.i, wordList.length), 0, obj); return; }
            if (!other) { wordList[idx] = obj; return; }
            // a card the step edited: put back only the fields the step changed (a review since then stays)
            var from = JSON.parse(other.j), cur = wordList[idx];
            Object.keys(obj).concat(Object.keys(from)).forEach(function(k) {
                if (JSON.stringify(obj[k]) === JSON.stringify(from[k])) return;
                if (obj[k] === undefined) delete cur[k]; else cur[k] = obj[k];
            });
        });
        saveWordList();
        if (wordlistView.style.display !== 'none') renderWordListItems();
        updateWordUndoUi();
    }
    function wordUndoStep() {
        var act = wordUndo.pop(); if (!act) return;
        wordApply(act.ch, 'b'); wordRedo.push(act); updateWordUndoUi();
        showToast('元に戻しました：' + act.label);
    }
    function wordRedoStep() {
        var act = wordRedo.pop(); if (!act) return;
        wordApply(act.ch, 'a'); wordUndo.push(act); updateWordUndoUi();
        showToast('やり直しました：' + act.label);
    }
    function updateWordUndoUi() {
        var u = document.getElementById('wordlist-undo'), r = document.getElementById('wordlist-redo');
        if (u) { u.disabled = !wordUndo.length; u.title = wordUndo.length ? '元に戻す：' + wordUndo[wordUndo.length - 1].label : '元に戻す'; }
        if (r) { r.disabled = !wordRedo.length; r.title = wordRedo.length ? 'やり直す：' + wordRedo[wordRedo.length - 1].label : 'やり直す'; }
    }

    // A badge's description fades after 3 seconds, or right away when you tap somewhere else
    var badgeTipFor = null;
    function hideBadgeTip() {
        if (!badgeTipFor) return;
        badgeTipFor = null;
        clearTimeout(window.toastTimeout);
        document.getElementById('app-toast').classList.remove('show');
    }
    document.addEventListener('click', function(e) { if (badgeTipFor && !e.target.closest('.badge')) hideBadgeTip(); }, true);
    window.addEventListener('scroll', function() { if (badgeTipFor) hideBadgeTip(); }, { passive: true });
    function showToast(msg, ms) {
        badgeTipFor = null;
        var t = document.getElementById('app-toast');
        t.textContent = msg;
        t.classList.add('show');
        clearTimeout(window.toastTimeout);
        window.toastTimeout = setTimeout(function() { t.classList.remove('show'); }, ms || 2200);
    }

    // Text of a block without furigana and answer numbers, plus the text nodes that make it up
    function collectText(block) {
        var walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT, {
            acceptNode: function(n) {
                return n.parentElement && n.parentElement.closest('rt, rp, .option-prefix, .blank-number, .kw-blank i, .ar-title, .ar-author, .ar-h-title, .ar-h-author, .ar-pgbadge') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
            }
        });
        var parts = [], text = '', n;
        while ((n = walker.nextNode())) { parts.push({ node: n, start: text.length }); text += n.data; }
        return { text: text, parts: parts };
    }

    // Index (in collectText's text) of the character under the point, or the nearest one within 20px, or -1
    function charIndexAtPoint(collected, x, y, anyDistance) {
        var range = document.createRange();
        var best = -1, bestDist = anyDistance ? Infinity : 900;   // otherwise within 30px
        for (var p = 0; p < collected.parts.length; p++) {
            var part = collected.parts[p];
            if (!anyDistance && collected.parts.length > 20) {      // long texts (the reader): skip lines nowhere near the finger
                range.selectNodeContents(part.node);
                var nb = range.getBoundingClientRect();
                if (x < nb.left - 40 || x > nb.right + 40 || y < nb.top - 40 || y > nb.bottom + 40) continue;
            }
            for (var i = 0; i < part.node.data.length; i++) {
                range.setStart(part.node, i);
                range.setEnd(part.node, i + 1);
                var rects = range.getClientRects();
                for (var r = 0; r < rects.length; r++) {
                    var rc = rects[r];
                    if (x >= rc.left && x <= rc.right && y >= rc.top && y <= rc.bottom) return part.start + i;
                    var dx = Math.max(rc.left - x, 0, x - rc.right), dy = Math.max(rc.top - y, 0, y - rc.bottom);
                    var d = dx * dx + dy * dy;
                    if (d < bestDist) { bestDist = d; best = part.start + i; }
                }
            }
        }
        return best;
    }

    function charKind(ch) {
        if (/[一-鿿々〆ヶ]/.test(ch)) return 'kanji';
        if (/[゠-ヿｦ-ﾟ]/.test(ch)) return 'kata';
        if (/[぀-ゟ]/.test(ch)) return 'hira';
        if (/[A-Za-z0-9０-９Ａ-Ｚａ-ｚ]/.test(ch)) return 'latin';
        return 'other';
    }

    // Word boundaries around index: Intl.Segmenter when available, otherwise runs of the same script
    function wordBoundsAt(text, idx) {
        if (idx < 0 || idx >= text.length || charKind(text[idx]) === 'other') return null;
        if (window.Intl && Intl.Segmenter) {
            try {
                var segs = Array.from(new Intl.Segmenter('ja', { granularity: 'word' }).segment(text));
                for (var i = 0; i < segs.length; i++) {
                    var sg = segs[i];
                    if (idx >= sg.index && idx < sg.index + sg.segment.length) {
                        if (sg.isWordLike === false) return null;
                        return { start: sg.index, end: sg.index + sg.segment.length };
                    }
                }
            } catch (e) { /* fall through to the simple rule */ }
        }
        var kind = charKind(text[idx]), start = idx, end = idx + 1;
        while (start > 0 && charKind(text[start - 1]) === kind) start--;
        while (end < text.length && charKind(text[end]) === kind) end++;
        // a kanji word usually keeps a little okurigana (e.g. 慎重, 懐く)
        if (kind === 'kanji') { var k = 0; while (end < text.length && k < 2 && charKind(text[end]) === 'hira') { end++; k++; } }
        return { start: start, end: end };
    }

    function contextAround(text, start, end) {
        var a = start, b = end;
        while (a > 0 && !/[。！？\n]/.test(text[a - 1])) a--;
        while (b < text.length && !/[。！？\n]/.test(text[b])) b++;
        if (b < text.length) b++;
        var ctx = text.slice(a, b).trim();
        if (ctx.length > 120) {
            var s0 = Math.max(0, start - a - 50);
            ctx = (s0 > 0 ? '…' : '') + ctx.slice(s0, s0 + 110) + '…';
        }
        return ctx;
    }

    function escapeHtml(t) {
        return String(t).replace(/[&<>"]/g, function(c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
    }

    function highlightIn(context, word) {
        var safe = escapeHtml(context);
        if (!word) return safe;
        var w = escapeHtml(word);
        var i = safe.indexOf(w);
        return i === -1 ? safe : safe.slice(0, i) + '<mark class="word-mark">' + w + '</mark>' + safe.slice(i + w.length);
    }

    function currentQuestionId() {
        return (currentQuestions.length && quizView.style.display !== 'none' && currentQuestions[currentIndex]) ? currentQuestions[currentIndex].id : null;
    }

    function findWordEntry(word) {
        var k = normWord(word);
        return wordList.find(function(e) { return normWord(e.word) === k; });
    }

    function lookUpMeaning(word) {
        var qid = wordSheetState && (wordSheetState.qid || null);
        var q = qid ? findQuestion(qid) : null;
        if (q && q.notes) {
            for (var k in q.notes) if (k === word || k.replace(/[なするだ]$/, '') === word) return q.notes[k];
        }
        return wordDefinitions[word] ? wordDefinitions[word].jp : '';
    }

    function renderWordSheet() {
        var st = wordSheetState;
        var input = document.getElementById('word-sheet-word');
        if (st.text) input.value = st.text.slice(st.start, st.end);
        var word = sheetWordAndReading().word;
        var existing = !st.editId && findWordEntry(word);
        document.getElementById('word-sheet-title').textContent = st.editId ? '単語を編集' : (existing ? '単語帳に登録済み' : '単語帳に追加');
        // Editing from the 単語帳 saves by itself when the sheet closes: one 閉じる button, no キャンセル
        document.getElementById('word-sheet-save').textContent = st.editId ? '閉じる' : (existing ? '更新する' : '単語帳に追加');
        document.getElementById('word-sheet-cancel').hidden = !!st.editId;
        document.getElementById('word-sheet-autosave').hidden = !st.editId;
        document.getElementById('word-sheet-context').innerHTML = st.context ? '例文：' + highlightIn(st.context, word) : '';
        wsReadingRender();
        ['word-grow-left', 'word-trim-left', 'word-trim-right', 'word-grow-right'].forEach(function(id) {
            document.getElementById(id).style.display = st.text ? '' : 'none';
        });
    }

    // Desktop-site mode on a phone shows the page shrunk (e.g. 40%). Show the sheet at normal phone size over what you're
    // looking at, so the browser doesn't zoom in on its small text box (and lose your place).
    function wsFitToScreen(sheet) {
        var vv = window.visualViewport, sc = vv ? vv.scale : 1;
        if (!vv || sc > 0.85) { sheet.style.scale = ''; sheet.style.width = ''; sheet.style.left = ''; sheet.style.bottom = ''; return; }
        var z = Math.min(1 / sc, 3);
        sheet.style.transformOrigin = 'left bottom';
        sheet.style.scale = z;
        sheet.style.width = (vv.width / z) + 'px';
        sheet.style.left = vv.offsetLeft + 'px';
        sheet.style.bottom = Math.max(0, window.innerHeight - vv.offsetTop - vv.height) + 'px';
    }
    // remember where the reader / page was, and go back there when the sheet closes
    function wsSavePlace() {
        var body = document.querySelector('#ar-view.active .ar-body'), book = body && body.querySelector('.ar-book');
        return { x: window.scrollX, y: window.scrollY, body: body, bodyTop: body ? body.scrollTop : 0, book: book, bookLeft: book ? book.scrollLeft : 0 };
    }
    function wsRestorePlace(pl) {
        if (!pl) return;
        var go = function() {
            window.scrollTo(pl.x, pl.y);
            if (pl.body && pl.body.isConnected) pl.body.scrollTop = pl.bodyTop;
            if (pl.book && pl.book.isConnected) pl.book.scrollLeft = pl.bookLeft;
        };
        go(); requestAnimationFrame(go); setTimeout(go, 350);      // again after the keyboard has gone away
    }
    function openWordSheet(state) {
        state.place = wsSavePlace();
        wsFitToScreen(document.getElementById('word-sheet'));
        wordSheetState = state;
        var word = state.text ? state.text.slice(state.start, state.end) : state.word;
        var br = !state.text && parseBracketFurigana(word);
        if (br) { state.furiSrc = br.source; state.readingOrig = br.reading; word = br.word; }
        state.plainOrig = word; state.readingEdited = false;
        var ent0 = state.editId ? wordList.find(function(e) { return e.id === state.editId; }) : null;
        var rdBox = document.getElementById('word-sheet-reading');
        rdBox.value = br ? toHiragana(br.reading) : (ent0 && ent0.reading) || localReading(word) || '';
        if (!br && ent0 && ent0.reading) state.readingOrig = ent0.reading;
        rdBox.hidden = true; document.getElementById('ws-reading-edit').hidden = false;
        document.getElementById('word-sheet-word').value = word;
        var existing = state.editId ? wordList.find(function(e) { return e.id === state.editId; }) : findWordEntry(word);
        var meaningEl = document.getElementById('word-sheet-meaning');
        meaningEl.value = existing && existing.meaning ? existing.meaning : lookUpMeaning(word);
        if (!existing) {
            var plain = (parseBracketFurigana(word) || { word: word }).word, dForm = dictionaryForm(plain);
            if (dForm) meaningEl.value = dForm.form + '\n' + (meaningEl.value || lookUpMeaning(dForm.form));
            meaningEl.value = meaningEl.value.replace(/\n$/, '');
        }
        delete meaningEl.dataset.edited;
        document.getElementById('word-sheet-def').value = existing && existing.writeDef ? existing.writeDef : '';
        renderWordSheet();
        state.origInput = document.getElementById('word-sheet-word').value;
        state.origReading = document.getElementById('word-sheet-reading').value;
        state.origMeaning = meaningEl.value;
        state.origDef = document.getElementById('word-sheet-def').value;
        definitionPopup.classList.remove('active');
        blankPopup.classList.remove('active');
        document.getElementById('app-toast').classList.remove('show');   // don't cover the sheet's buttons
        document.getElementById('word-sheet').classList.add('active');
        document.getElementById('word-sheet-dim').classList.add('active');
    }

    // ---------- Your own furigana: 痴[ち]人[じん]の愛[あい] ----------
    // The kana in [ ] belongs to the kanji just before it (or, if there are none, to the text since the last ] or space).
    function parseBracketFurigana(src) {
        src = String(src || '').trim();
        if (!/\[[^\]]*\]/.test(src)) return null;
        var segs = [], buf = '', i = 0;
        while (i < src.length) {
            var c = src[i];
            if (c === '[') {
                var close = src.indexOf(']', i);
                if (close === -1) { buf += src.slice(i); break; }
                var rt = src.slice(i + 1, close).trim();
                var k = buf.length;
                while (k > 0 && hasKanji(buf[k - 1])) k--;
                if (k === buf.length) k = 0;                     // no kanji right before: use the whole run
                if (k > 0) segs.push({ text: buf.slice(0, k) });
                if (buf.slice(k)) segs.push(rt ? { base: buf.slice(k), rt: rt } : { text: buf.slice(k) });
                buf = ''; i = close + 1;
            } else if (c === ' ' || c === '　') {
                if (buf) segs.push({ text: buf });
                buf = ''; i++;
            } else { buf += c; i++; }
        }
        if (buf) segs.push({ text: buf });
        var word = segs.map(function(s) { return s.base || s.text; }).join('');
        var reading = segs.map(function(s) { return s.rt || s.text; }).join('');
        var source = segs.map(function(s) { return s.base ? s.base + '[' + s.rt + ']' : s.text; }).join('');
        return word ? { word: word, reading: reading, source: source, segs: segs } : null;
    }
    function bracketFuriganaHtml(spec) {
        var p = typeof spec === 'string' ? parseBracketFurigana(spec) : spec;
        if (!p) return escapeHtml(spec || '');
        return p.segs.map(function(s) {
            if (!s.base) return escapeHtml(s.text);
            var sp = Array.from(s.base).length > 1 ? rubySplitFor(s.base, s.rt) : null;          // 実社会[じっしゃかい] → 実(じっ)社(しゃ)会(かい)
            return '<ruby>' + (sp ? sp.map(function(x) { return escapeHtml(x[0]) + '<rt>' + escapeHtml(x[1]) + '</rt>'; }).join('') : escapeHtml(s.base) + '<rt>' + escapeHtml(s.rt) + '</rt>') + '</ruby>';
        }).join('');
    }
    // ---------- furigana per kanji ----------
    // Every reading the app has seen over a single kanji (the questions' ruby, the reading books' furigana, the
    // 単語帳's own [ ] furigana) is collected; a word's reading is then split so that each kanji gets one of its
