    var MEM_BACKS = ['seigaiha', 'asanoha', 'shippo', 'kikko', 'kanoko', 'tatewaki', 'kagome'];
    var WAGARA_INKS = ['#2d4f7f', '#b8312f', '#3f6f4a', '#6b4a7e', '#8f3b2b'];      // 藍・朱・松葉・江戸紫・弁柄
    function wgMix(a, b, t) {          // a over b at strength t, as a hex color
        var p = function(h, i) { return parseInt(h.substr(1 + i * 2, 2), 16); };
        return '#' + [0, 1, 2].map(function(i) { return ('0' + Math.round(p(b, i) + (p(a, i) - p(b, i)) * t).toString(16)).slice(-2); }).join('');
    }
    function wagaraPick() {
        var v = document.getElementById('flash-view');
        if (!v) return;
        var last = getSetting('wgLast', ''), pool = WAGARA.filter(function(w) { return w[0] !== last; });
        var w = pool[Math.floor(Math.random() * pool.length)], ink = WAGARA_INKS[Math.floor(Math.random() * WAGARA_INKS.length)];
        setSetting('wgLast', w[0]);
        var dark = document.documentElement.classList.contains('dark');
        var bg = dark ? '#1c1f26' : '#f3ecdc';
        var fg = dark ? wgMix(wgMix('#ffffff', ink, 0.55), bg, w[4] === 'fill' ? 0.16 : 0.24) : wgMix(ink, bg, w[4] === 'fill' ? 0.17 : 0.3);
        v.style.setProperty('--wg', 'url("data:image/svg+xml,' + encodeURIComponent(w[7].replace(/__F__/g, fg).replace(/__B__/g, bg)) + '")');
        v.style.setProperty('--wg-size', w[5] + 'px ' + w[6] + 'px');
        v.style.setProperty('--wg-bg', bg);
        // the same pattern, in cream on 藍, for the backs of the 神経衰弱 cards (a little smaller, so the motif reads on a small card)
        // the 神経衰弱 card backs draw from their own short list (chosen on the 札の裏えらび page), in cream on 藍
        var backs = WAGARA.filter(function(x) { return MEM_BACKS.indexOf(x[0]) > -1; }), wb = backs[Math.floor(Math.random() * backs.length)] || w;
        var mb = '#22406f', bfg = wgMix('#f3ecdc', mb, wb[4] === 'fill' ? 0.2 : 0.32), k = 0.62;
        v.style.setProperty('--wg-back', 'url("data:image/svg+xml,' + encodeURIComponent(wb[7].replace(/__F__/g, bfg).replace(/__B__/g, mb)) + '")');
        v.style.setProperty('--wg-back-size', (wb[5] * k).toFixed(1) + 'px ' + (wb[6] * k).toFixed(1) + 'px');
    }
