        document.querySelector('#flash-view .flash-progress').textContent = '';
        var seg = function(key, label, items) {
            return '<div class="mset-row"><div class="mset-label">' + label + '</div><div class="mset-seg" data-key="' + key + '">' +
                items.map(function(it) { return '<button data-v="' + it[0] + '"' + (String(o[key]) === String(it[0]) ? ' class="on"' : '') + '>' + it[1] + '</button>'; }).join('') + '</div></div>';
        };
