                return '<button class="mem-card' + (c.side === 'L' ? ' word' : '') + '" data-i="' + i + '" style="animation-delay:' + (i * 30) + 'ms" aria-label="カード"><span class="mem-inner"><span class="mem-back" aria-hidden="true"></span><span class="mem-front">' + face(c) + '</span></span></button>';
