                                best: best.isNew ? '🏆 自己ベスト更新！（前回まで ' + best.old + '手）' : best.first ? 'この設定の初記録：' + moves + '手' : 'この設定の自己ベスト：' + best.old + '手',
                                chips: [['ペア', pairs], ['手数', moves], ['最高コンボ', wq.bestCombo], ['時間', wqClock(ms)]],
