            var bk = 'cloze:' + again.how + ':' + again.count + ':' + again.hint, best = wqBest(bk, Math.round(pct));
            wqResult({ title: '穴埋め', pct: pct, big: wq.ok, bigLabel: '/ ' + n,
                best: best.isNew ? '🏆 自己ベスト更新！（前回まで ' + best.old + '%）' : '',
                chips: [['正答率', Math.round(pct) + '%'], ['最高連続', wq.bestStreak + '問'], ['時間', wqClock(Date.now() - wq.start)]],
                missed: wq.missed, again: function() { runWordCloze(again); } });
